// ============================================================================
// 4. ENGINEERING TRIGGER ENGINE
// ============================================================================

pub struct EngineeringTriggerEngine;

impl EngineeringTriggerEngine {
    pub fn evaluate(
        search_text: &str,
        tool_keywords: Option<&str>,
        target_file_or_cmd: Option<&str>,
        recent_exit_code: Option<i32>,
    ) -> Option<(EngineeringPromptId, u32, String)> {
        let text_lower = search_text.to_lowercase();
        let kw_lower = tool_keywords.unwrap_or("").to_lowercase();
        let target_lower = target_file_or_cmd.unwrap_or("").to_lowercase();
        let combined = format!("{} {} {}", text_lower, kw_lower, target_lower);

        // Signal 0: Slash Command Dispatch (100% confidence)
        let trimmed = text_lower.trim();
        if trimmed.starts_with("/grill") || trimmed.contains("/grill ") || trimmed.starts_with("/grill_me") {
            return Some((EngineeringPromptId::GrillArchitect, 100, "/grill".into()));
        }
        if trimmed.starts_with("/design") || trimmed.starts_with("/divergent") {
            return Some((EngineeringPromptId::DesignItTwice, 100, "/design".into()));
        }
        if trimmed.starts_with("/tdd") || trimmed.contains("/tdd ") {
            return Some((EngineeringPromptId::TddRedGreenRefactor, 100, "/tdd".into()));
        }
        if trimmed.starts_with("/tickets") || trimmed.starts_with("/spec") || trimmed.contains("/tickets ") {
            return Some((EngineeringPromptId::SpecToTickets, 100, "/tickets".into()));
        }
        if trimmed.starts_with("/diagnose") || trimmed.contains("/diagnose ") || trimmed.starts_with("/bug") {
            return Some((EngineeringPromptId::BugDiagnosisRootCause, 100, "/diagnose".into()));
        }
        if trimmed.starts_with("/adr") || trimmed.starts_with("/domain") || trimmed.contains("/adr ") {
            return Some((EngineeringPromptId::DomainModelingAdr, 100, "/adr".into()));
        }
        if trimmed.starts_with("/wayfinding") || trimmed.starts_with("/wayfinder") || trimmed.starts_with("/nav") || trimmed.starts_with("/fog") {
            return Some((EngineeringPromptId::WayfinderCodebaseNavigator, 100, "/wayfinding".into()));
        }
        if trimmed.starts_with("/triage") || trimmed.starts_with("/scope") || trimmed.starts_with("/git-guardrails") {
            return Some((EngineeringPromptId::TriageAndScopeGuardrails, 100, "/triage".into()));
        }
        if trimmed.starts_with("/prototype") || trimmed.starts_with("/spike") {
            return Some((EngineeringPromptId::RapidPrototypingUiLogic, 100, "/prototype".into()));
        }
        if trimmed.starts_with("/wizard") || trimmed.starts_with("/cli-wizard") || trimmed.starts_with("/teach") {
            return Some((EngineeringPromptId::WizardGuidedArchitect, 100, "/wizard".into()));
        }
        if trimmed.starts_with("/dom") || trimmed.starts_with("/dom-index") {
            return Some((EngineeringPromptId::AtomicDomIndexingDoctrine, 100, "/dom".into()));
        }
        if trimmed.starts_with("/action-decider") || trimmed.starts_with("/browser-action") {
            return Some((EngineeringPromptId::FastBrowserActionDecider, 100, "/action-decider".into()));
        }
        if trimmed.starts_with("/anti-block") || trimmed.starts_with("/headless-resilience") {
            return Some((EngineeringPromptId::HeadlessResilienceAntiBlock, 100, "/anti-block".into()));
        }
        if trimmed.starts_with("/transcript") || trimmed.starts_with("/forensics") {
            return Some((EngineeringPromptId::AgentTranscriptForensics, 100, "/transcript".into()));
        }
        if trimmed.starts_with("/session") || trimmed.starts_with("/continuity") {
            return Some((EngineeringPromptId::DesktopAgentSessionContinuity, 100, "/session".into()));
        }
        if trimmed.starts_with("/memory") || trimmed.starts_with("/tiering") || trimmed.starts_with("/retro") {
            return Some((EngineeringPromptId::HeterogeneousMemoryTiering, 100, "/memory".into()));
        }

        // Signal 1: Sensory Runtime Event (Non-Zero Exit Code or Crash) -> BugDiagnosisRootCause
        if let Some(code) = recent_exit_code {
            if code != 0 {
                return Some((
                    EngineeringPromptId::BugDiagnosisRootCause,
                    95,
                    format!("runtime exit code non-zero ({})", code),
                ));
            }
        }
        if combined.contains("panic!") || combined.contains("segmentation fault") || combined.contains("sigsegv") || combined.contains("failed with exit code") || combined.contains("execution failed") {
            return Some((
                EngineeringPromptId::BugDiagnosisRootCause,
                90,
                "runtime crash/panic signal".into(),
            ));
        }

        // Signal 2: Sensory File Inspection & Target Path matching
        if !target_lower.is_empty() {
            // TDD (3): *.test.*, *.spec.*, __tests__/*, test_*.rs
            if target_lower.contains(".test.") || target_lower.contains(".spec.") || target_lower.contains("__tests__")
                || target_lower.contains("/tests/") || target_lower.starts_with("tests/") || target_lower.contains("test_") {
                return Some((EngineeringPromptId::TddRedGreenRefactor, 90, format!("file target: {}", target_file_or_cmd.unwrap_or(""))));
            }

            // ADR & Migrations & Domain Modeling (6)
            if target_lower.contains("adr/") || target_lower.contains(".adr.") || target_lower.contains("glossary") || target_lower.contains("migrations/") || target_lower.contains("migration") {
                return Some((EngineeringPromptId::DomainModelingAdr, 95, format!("adr/migration target: {}", target_file_or_cmd.unwrap_or(""))));
            }

            // Git Guardrails & Triage (8)
            if target_lower.starts_with("git commit") || target_lower.starts_with("git reset") || target_lower.starts_with("git push") || target_lower.contains("pr_template") || target_lower.contains("issue_template") {
                return Some((EngineeringPromptId::TriageAndScopeGuardrails, 90, format!("git command target: {}", target_file_or_cmd.unwrap_or(""))));
            }

            // Spec & Tickets (4)
            if target_lower.contains("tickets/") || target_lower.contains(".ticket.") || target_lower.contains("spec.md") || target_lower.contains("specification.md") {
                return Some((EngineeringPromptId::SpecToTickets, 90, format!("spec file target: {}", target_file_or_cmd.unwrap_or(""))));
            }

            // Grill Architect (1)
            if target_lower.contains(".plan.md") || target_lower.contains("rencana") || target_lower.contains("design.md") {
                return Some((EngineeringPromptId::GrillArchitect, 90, format!("plan file target: {}", target_file_or_cmd.unwrap_or(""))));
            }

            // Transcript Forensics (14)
            if target_lower.contains("transcript.jsonl") || target_lower.contains("transcript_full.jsonl") {
                return Some((EngineeringPromptId::AgentTranscriptForensics, 90, format!("transcript target: {}", target_file_or_cmd.unwrap_or(""))));
            }

            // Session Continuity (15)
            if target_lower.contains("session_") || target_lower.contains("session.json") {
                return Some((EngineeringPromptId::DesktopAgentSessionContinuity, 90, format!("session target: {}", target_file_or_cmd.unwrap_or(""))));
            }
        }

        // Signal 3: Keywords & Semantic Intent Matching
        if combined.contains("deep module") || combined.contains("information hiding") || combined.contains("narrow api") || combined.contains("domain model") || combined.contains("adr") {
            return Some((EngineeringPromptId::DomainModelingAdr, 85, "semantic domain/architecture intent".into()));
        }
        if combined.contains("red green refactor") || combined.contains("tdd") || combined.contains("unit test") || combined.contains("test seam") {
            return Some((EngineeringPromptId::TddRedGreenRefactor, 85, "semantic tdd intent".into()));
        }
        if combined.contains("root cause") || combined.contains("reproduce bug") || combined.contains("diagnose bug") || combined.contains("hard bug") {
            return Some((EngineeringPromptId::BugDiagnosisRootCause, 85, "semantic bug diagnosis intent".into()));
        }

        None
    }

    pub fn compose_prompt_injection(id: EngineeringPromptId, matched_trigger: &str) -> String {
        let content = id.compose_with_breadcrumbs();
        format!(
            "<ACTIVE_ENGINEERING_DOCTRINE id=\"{}\" slug=\"{}\" trigger=\"{}\">\n{}\n</ACTIVE_ENGINEERING_DOCTRINE>",
            id.id_num(),
            id.slug(),
            matched_trigger,
            content
        )
    }

    pub fn scan_external_linked_topics(
        id: &EngineeringPromptId,
        workspace_dir: Option<&Path>,
        engine_root: Option<&Path>,
    ) -> Vec<ExternalLinkedTopic> {
        let mut dirs = Vec::new();
        if let Some(ws) = workspace_dir {
            dirs.push(ws.join("agents").join("system"));
            dirs.push(ws.join(".fl_brain").join("directives"));
        }
        if let Some(eng) = engine_root {
            dirs.push(eng.join("agents").join("system"));
            dirs.push(eng.join(".fl_brain").join("directives"));
        }

        let mut topics = Vec::new();
        let target_slug = id.slug().to_lowercase();
        let target_id_str = format!("0{}", id.id_num());

        for dir in dirs {
            if !dir.is_dir() {
                continue;
            }
            if let Ok(entries) = fs::read_dir(dir) {
                for entry in entries.flatten() {
                    let path = entry.path();
                    if path.extension().map(|e| e == "md").unwrap_or(false) {
                        if let Ok(text) = fs::read_to_string(&path) {
                            if let Some(topic) = Self::parse_external_topic(&text, path, &target_slug, &target_id_str) {
                                topics.push(topic);
                            }
                        }
                    }
                }
            }
        }

        topics
    }

    fn parse_external_topic(
        text: &str,
        path: PathBuf,
        target_slug: &str,
        target_id_str: &str,
    ) -> Option<ExternalLinkedTopic> {
        let parts: Vec<&str> = text.split("---").collect();
        if parts.len() < 3 {
            return None;
        }
        let yaml_block = parts[1];
        let mut trigger_id = String::new();
        let mut name = String::new();
        let mut guidance = String::new();
        let mut bait_keywords = Vec::new();
        let mut linked_doctrines = Vec::new();
        let mut in_bait = false;
        let mut in_linked = false;

        for line in yaml_block.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("trigger_id:") {
                trigger_id = trimmed.trim_start_matches("trigger_id:").trim().trim_matches('"').to_string();
                in_bait = false;
                in_linked = false;
            } else if trimmed.starts_with("name:") {
                name = trimmed.trim_start_matches("name:").trim().trim_matches('"').to_string();
                in_bait = false;
                in_linked = false;
            } else if trimmed.starts_with("guidance:") {
                guidance = trimmed.trim_start_matches("guidance:").trim().trim_matches('"').to_string();
                in_bait = false;
                in_linked = false;
            } else if trimmed.starts_with("bait_keywords:") {
                in_bait = true;
                in_linked = false;
            } else if trimmed.starts_with("linked_doctrines:") {
                in_linked = true;
                in_bait = false;
            } else if trimmed.starts_with("- ") {
                let val = trimmed.trim_start_matches("- ").trim().trim_matches('"').to_string();
                if in_bait {
                    bait_keywords.push(val);
                } else if in_linked {
                    linked_doctrines.push(val);
                }
            } else if !trimmed.starts_with('#') && trimmed.contains(':') {
                in_bait = false;
                in_linked = false;
            }
        }

        let is_linked = linked_doctrines.iter().any(|d| {
            let dl = d.to_lowercase();
            dl == target_slug
                || dl.contains(target_slug)
                || dl.starts_with(target_id_str)
                || (target_slug == "diagnosing_hard_bugs" && (dl == "01_diagnosing_hard_bugs" || dl.contains("diagnosing_hard_bugs")))
        });

        if is_linked {
            Some(ExternalLinkedTopic {
                trigger_id,
                name,
                file_path: path,
                guidance,
                bait_keywords,
                linked_doctrines,
            })
        } else {
            None
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_engineering_doctrines_unseal() {
        let p1 = EngineeringEnclave::get_prompt(EngineeringPromptId::GrillArchitect);
        assert!(!p1.is_empty());
        assert!(p1.contains("GRILL_ARCHITECT_DOCTRINE") || p1.contains("INTERROGATE ASSUMPTIONS"));

        let p_tdd = EngineeringEnclave::get_prompt(EngineeringPromptId::TddRedGreenRefactor);
        assert!(!p_tdd.is_empty());
        assert!(p_tdd.contains("TDD") || p_tdd.contains("TEST"));
    }

    #[test]
    fn test_strict_white_label_and_zero_leaks() {
        let all = EngineeringEnclave::all_prompts();
        for (id, content) in all {
            let lower = content.to_lowercase();
            assert!(!lower.contains("mattpocock"), "Prompt {:?} leaked mattpocock!", id);
            assert!(!lower.contains("claude code"), "Prompt {:?} leaked claude code!", id);
            assert!(!content.contains("AWENKAUDICO"), "Prompt {:?} leaked AWENKAUDICO!", id);
            assert!(!content.contains("TEGUHFX"), "Prompt {:?} leaked TEGUHFX!", id);
        }
    }

    #[test]
    fn test_enclave_resolve_id() {
        assert_eq!(EngineeringEnclave::resolve_id("1"), Some(EngineeringPromptId::GrillArchitect));
        assert_eq!(EngineeringEnclave::resolve_id("3"), Some(EngineeringPromptId::TddRedGreenRefactor));
        assert_eq!(EngineeringEnclave::resolve_id("test_driven_development"), Some(EngineeringPromptId::TddRedGreenRefactor));
        assert_eq!(EngineeringEnclave::resolve_id("tdd_red_green_refactor"), Some(EngineeringPromptId::TddRedGreenRefactor));
        assert_eq!(EngineeringEnclave::resolve_id("non_existent"), None);
    }

    #[test]
    fn test_dynamic_reverse_linking_bridge_from_agents_system() {
        let temp_dir = std::env::temp_dir().join(format!("flowork_test_revlink_{}", std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
        let sys_dir = temp_dir.join("agents").join("system");
        fs::create_dir_all(&sys_dir).unwrap();

        let mock_directive = r#"---
trigger_id: SYS-THERMAL-GUARD
name: System Thermal Overload Guard
scopes:
  - universal_all
linked_doctrines:
  - 01_diagnosing_hard_bugs
guidance: High CPU temperature alert and thermal throttling mitigation
bait_keywords:
  - cpu throttle
  - overheating
  - thermal guard
conditions:
  cpu_temp_celsius: ">=80"
---
# Host Thermal Protection Directive
The host CPU temperature is exceeding 80°C.
"#;
        fs::write(sys_dir.join("thermal_guard.md"), mock_directive).unwrap();

        // 1. BugDiagnosisRootCause dynamically discovers the external thermal guard
        let breadcrumbs = EngineeringPromptId::BugDiagnosisRootCause.compose_with_breadcrumbs_scoped(Some(&temp_dir), None);
        assert!(breadcrumbs.contains("Active External System Directives & Live Extensions (Cognitive Backlinks)"));
        assert!(breadcrumbs.contains("System Thermal Overload Guard"));
        assert!(breadcrumbs.contains("cpu throttle, overheating, thermal guard"));
        assert!(breadcrumbs.contains("High CPU temperature alert and thermal throttling mitigation"));

        // 2. TddRedGreenRefactor is NOT linked to thermal guard
        let tdd_breadcrumbs = EngineeringPromptId::TddRedGreenRefactor.compose_with_breadcrumbs_scoped(Some(&temp_dir), None);
        assert!(!tdd_breadcrumbs.contains("System Thermal Overload Guard"));

        let _ = fs::remove_dir_all(&temp_dir);
    }
}
